import { Moon, Sun } from 'lucide-react';

// ---------------------------------------------------------------------------
// EN-TÊTE COMMUN À TOUTES LES APPS DU TOOLBOX
//
// Le bandeau est identique partout : logo cliquable + nom de l'app à gauche,
// bascule jour/nuit puis bouton de retour au Toolbox à droite, et sous eux le
// nom et le titre du poste de la personne connectée.
//
// RIEN DE PROPRE À UNE APP NE VA DANS CE BANDEAU. Les onglets, exports, menus
// et autres boutons descendent dans une barre d'outils sous le bandeau.
//
// Props :
//   titre       nom de l'app, en majuscules à l'écran
//   sousTitre   une ligne qui dit ce que l'app fait
//   mode        'day' ou 'night'
//   onChangerMode(mode)   appelé par la bascule
//   nom, poste  la personne connectée (fournis par GardeConnexion)
//   onAccueil() appelé au clic sur le logo — ramène l'app à son écran
//               d'accueil; le retour en haut de page est fait ici.
// ---------------------------------------------------------------------------

const LOGO_PEP = 'data:image/png;base64,';

const ROUGE = '#c41230';
const NAVY_JOUR = '#14213d';
const NAVY_NUIT = '#0f2138';
const HAUTEUR = 58; // hauteur commune des deux colonnes — c'est ce qui balance le bandeau

export default function EnTeteApp({ titre, sousTitre, mode = 'day', onChangerMode, nom, poste, onAccueil }) {
  function clicLogo(e) {
    e.preventDefault();
    if (onAccueil) onAccueil();
    if (typeof window !== 'undefined') window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ height: 4, background: ROUGE }} />
      <header style={{
        background: mode === 'night' ? NAVY_NUIT : NAVY_JOUR,
        display: 'flex', alignItems: 'stretch', justifyContent: 'space-between',
        gap: 16, padding: '13px 20px', flexWrap: 'wrap',
      }}>

        {/* Gauche — logo cliquable et identité de l'app */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 13, minWidth: 0, minHeight: HAUTEUR }}>
          <a
            href="#"
            onClick={clicLogo}
            title="Retour à l'accueil de l'app"
            style={{ display: 'block', lineHeight: 0, cursor: 'pointer' }}
          >
            <img
              src={LOGO_PEP}
              alt="Les Entreprises PEP2000"
              style={{ height: HAUTEUR, width: 'auto', display: 'block', flexShrink: 0 }}
            />
          </a>
          <div style={{ minWidth: 0 }}>
            <h1 style={{
              margin: 0, color: '#fff', fontSize: 19, fontWeight: 700,
              textTransform: 'uppercase', letterSpacing: 0.5, lineHeight: 1.15,
            }}>
              {titre}
            </h1>
            {sousTitre && (
              <p style={{ margin: '2px 0 0', color: '#9aa5c0', fontSize: 12.5 }}>{sousTitre}</p>
            )}
          </div>
        </div>

        {/* Droite — commandes en haut, personne connectée en bas */}
        <div style={{
          display: 'flex', flexDirection: 'column', alignItems: 'flex-end',
          justifyContent: 'space-between', gap: 8, marginLeft: 'auto', minHeight: HAUTEUR,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {onChangerMode && (
              <div style={{
                display: 'flex', border: '1px solid rgba(255,255,255,0.3)',
                borderRadius: 16, overflow: 'hidden',
              }}>
                {[
                  { id: 'day', label: 'Jour', Icon: Sun },
                  { id: 'night', label: 'Nuit', Icon: Moon },
                ].map(({ id, label, Icon }) => (
                  <button
                    key={id}
                    onClick={() => onChangerMode(id)}
                    title={label}
                    aria-label={label}
                    style={{
                      background: mode === id ? ROUGE : 'transparent',
                      color: mode === id ? '#fff' : '#9aa5c0',
                      border: 'none', padding: '4px 9px', cursor: 'pointer',
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                    }}
                  >
                    <Icon size={13} />
                  </button>
                ))}
              </div>
            )}

            <a href="/" style={{
              color: '#fff', background: 'rgba(255,255,255,0.15)',
              border: '1px solid rgba(255,255,255,0.35)', borderRadius: 5,
              padding: '6px 11px', fontSize: 10.5, fontWeight: 600,
              whiteSpace: 'nowrap', textDecoration: 'none', display: 'inline-block',
            }}>
              &#8592; Retour au Toolbox PEP
            </a>
          </div>

          <div style={{
            display: 'flex', flexDirection: 'column', alignItems: 'flex-end',
            textAlign: 'right', whiteSpace: 'nowrap',
          }}>
            <span style={{ color: '#fff', fontSize: 13, fontWeight: 700, lineHeight: 1.3 }}>{nom}</span>
            {poste && (
              <span style={{ color: '#9aa5c0', fontSize: 11.5, lineHeight: 1.3 }}>{poste}</span>
            )}
          </div>
        </div>

      </header>
    </div>
  );
}
